sqlite3 -json "/data/arabic_dict.db" "SELECT e.id AS entry_id, e.dictionary_id, e.headword, e.headword_norm, e.root, e.root_source, e.pos, e.definitions_text, e.translation_en, e.domain, d.key AS dict_key, d.name_ar AS dict_name_ar, d.source_type, d.period, d.author, d.death_year FROM entries e JOIN dictionaries d ON e.dictionary_id = d.id WHERE e.headword_norm IN ('اتصال','الاتصال','تواصل','التواصل','وصال','الوصال','صلة','الصلة','منفذ','المنفذ','موصل','الموصل') ORDER BY e.headword_norm, d.source_type, d.death_year ASC NULLS LAST, d.name_ar;" 2>/dev/null | python3 -c "
import json, sys
data = json.load(sys.stdin)
# Group by headword_norm
from collections import defaultdict
groups = defaultdict(list)
for r in data:
    groups[r['headword_norm']].append(r)
for hw, rows in sorted(groups.items()):
    print(f'\n=== {hw} ({len(rows)} entries) ===')
    for r in rows[:5]:
        print(f'  [{r[\"entry_id\"]}] {r[\"headword\"]} | {r[\"dict_name_ar\"]} ({r[\"source_type\"]}) | root={r[\"root\"]} | pos={r[\"pos\"]}')
        if r['definitions_text']:
            print(f'    DEF: {r[\"definitions_text\"][:200]}')
        if r['translation_en']:
            print(f'    EN: {r[\"translation_en\"]} | domain: {r[\"domain\"]}')
    if len(rows) > 5:
        print(f'  ... +{len(rows)-5} more')
